SELECT s.id, s.symbol, s.interval_code, s.candle_open_time, s.generated_at, s.original_decision, s.decision, s.total_score, s.confluence_status, s.confluence_entry_allowed, s.confluence_higher_decision, s.primary_blocking_stage, LEFT(s.final_decision_explanation,1500) AS fde, LEFT(CAST(s.decision_path AS CHAR),6000) AS path FROM trade_signal s WHERE s.id IN (156721,159407,165415,167616,171559,176403,176529,176655,176792,176934,176710) ORDER BY s.symbol, s.generated_at